//! `DateTime::format()`, `date()` and `gmdate()` against PHP 8.5.13 (`tests/vectors/format.json`, generated by
//! `format.gen.php`; regenerate with `crates/twig-date/tests/vectors/regen.sh format`, which needs the
//! `twig-oracle:3.31.1` Docker image from `research/php-oracle`).

mod common;

use common::*;
use twig_date::{DateObject, TimeZoneObject, classes, functions};
use twig_value::Value;

/// `new DateTime('@ts')`, `setTimezone(new DateTimeZone(zone))`, `setMicrosecond(us)`.
fn instant(c: &Ctx, zone: &str, ts: i64, us: i64) -> twig_value::ObjectRef {
    let mut diags = Vec::new();
    let d = DateObject::construct(
        &c.ctx,
        classes::datetime(),
        format!("@{ts}").as_bytes(),
        None,
    )
    .unwrap();
    let tz = TimeZoneObject::construct(&c.ctx, zone.as_bytes()).unwrap();
    call(&d, "setTimezone", vec![Value::Object(tz)], &mut diags).unwrap();
    call(&d, "setMicrosecond", vec![Value::Int(us)], &mut diags).unwrap();
    assert!(diags.is_empty());
    d
}

#[test]
fn format_letters() {
    let v = load("format");
    let fmt = s(&v["fmt"]);
    let c = Ctx::new();
    let mut r = Report::new("DateTime::format() letters");
    for case in v["letters"].as_array().unwrap() {
        let (zone, ts, us) = (s(&case[0]), i(&case[1]), i(&case[2]));
        let d = instant(&c, zone, ts, us);
        let got = call(&d, "format", vec![php_str(fmt)], &mut Vec::new()).unwrap();
        r.eq(str_val(&got), s(&case[3]).to_owned(), || {
            format!("{zone} @{ts}.{us:06}")
        });
    }
    r.finish();
}

#[test]
fn date_and_gmdate() {
    let v = load("format");
    let fmt = s(&v["fmt"]).as_bytes();
    let c = Ctx::new();
    let mut r = Report::new("date()/gmdate()");
    for case in v["date"].as_array().unwrap() {
        let (zone, ts) = (s(&case[0]), i(&case[1]));
        assert!(
            c.ctx
                .default_timezone_set(zone.as_bytes(), &mut Vec::new())
                .unwrap()
        );
        let got = functions::date(&c.ctx, fmt, Some(ts)).unwrap();
        r.eq(enc(got.as_bytes()), s(&case[2]).to_owned(), || {
            format!("date() {zone} @{ts}")
        });
        let got = functions::gmdate(&c.ctx, fmt, Some(ts)).unwrap();
        r.eq(enc(got.as_bytes()), s(&case[3]).to_owned(), || {
            format!("gmdate() {zone} @{ts}")
        });
    }
    r.finish();
}

#[test]
fn special_formats() {
    let v = load("format");
    let c = Ctx::new();
    let mut r = Report::new("special formats");
    for case in v["formats"].as_array().unwrap() {
        let (zone, ts, us) = (s(&case[0]), i(&case[1]), i(&case[2]));
        let f = bytes(&case[3]);
        let d = instant(&c, zone, ts, us);
        let got = d.downcast_ref::<DateObject>().unwrap().format(&f).unwrap();
        r.eq(enc(got.as_bytes()), s(&case[4]).to_owned(), || {
            format!("{zone} @{ts} format {:?}", enc(&f))
        });
    }
    r.finish();
}
